// Release artwork only. No secrets, member data or private answers.
export const CARD_DESIGNS=[{"id":"light","name":"Porch Light","description":"A warm reminder that showing up matters.","lines":["I kept","showing up."],"caption":"There is a place for you on the porch.","background":"#263F38","ink":"#FFFFFF","accent":"#D9A65B","motif":"arch"},{"id":"morning","name":"New Morning","description":"A fresh start, one honest day at a time.","lines":["One honest","day."],"caption":"This day is enough to begin with.","background":"#F6F5F2","ink":"#253A32","accent":"#A7B8A8","motif":"sunrise"},{"id":"steps","name":"Steady Steps","description":"For the small steps that deserve a little credit.","lines":["Small steps.","Still moving."],"caption":"Your pace can be your own.","background":"#DDE6DE","ink":"#253A32","accent":"#587563","motif":"steps"},{"id":"begin","name":"Room to Begin","description":"A little room for the next useful step.","lines":["There is room","to begin again."],"caption":"You can start with one useful step.","background":"#F3E2D4","ink":"#583E32","accent":"#B16F4C","motif":"doorway"},{"id":"together","name":"Shared Strength","description":"A reminder that support belongs in the picture.","lines":["I made room","for support."],"caption":"You deserve to be heard.","background":"#243D50","ink":"#FFFFFF","accent":"#B8D2CB","motif":"circles"},{"id":"quiet","name":"Quiet Progress","description":"For progress that does not need an audience.","lines":["Quiet progress","still counts."],"caption":"You are allowed to notice what helped.","background":"#F8F2E7","ink":"#3E4B3F","accent":"#788A69","motif":"leaves"}];
export const CARD_BRAND_LOGO="data:image/png;base64,";
export function renderSupporterCardSvg(id){
 const d=CARD_DESIGNS.find(design=>design.id===id);if(!d)throw Error('Unknown design');
 // All content is fixed release artwork; no account or reflection input is accepted.
 const esc=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
 let motif='';
 if(d.motif==='arch' || d.motif==='sunrise')motif='<path d="M410 500 A190 190 0 0 1 790 500 Z" fill="'+d.accent+'"/><path d="M360 500H840"/>';
 else if(d.motif==='steps')motif='<path stroke-width="9" d="M350 490H460V440H570V390H680V340H830"/>';
 else if(d.motif==='doorway')motif='<path stroke-width="7" d="M475 495V415A125 125 0 0 1 725 415V495"/><path d="M430 500H770"/>';
 else if(d.motif==='circles')motif=[500,600,700].map(x=>'<circle cx="'+x+'" cy="415" r="82"/>').join('');
 else motif='<path d="M600 500C585 435 605 380 655 325"/>'+[[590,455,-34],[620,420,37],[615,380,-34],[655,350,37]].map(([x,y,r])=>'<ellipse cx="'+x+'" cy="'+y+'" rx="40" ry="15" transform="rotate('+r+' '+x+' '+y+')"/>').join('');
 return '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="0 0 1200 1200"><rect width="1200" height="1200" fill="'+d.background+'"/><rect x="40" y="40" width="1120" height="1120" fill="none" stroke="'+d.accent+'" stroke-width="4"/><g fill="none" stroke="'+d.accent+'" stroke-width="4">'+motif+'</g><g text-anchor="middle" font-family="Arial, sans-serif" fill="'+d.ink+'"><text x="600" y="620" font-size="76" font-weight="bold">'+esc(d.lines[0])+'</text><text x="600" y="715" font-size="76" font-weight="bold">'+esc(d.lines[1])+'</text><text x="600" y="825" font-size="31">'+esc(d.caption)+'</text><text x="600" y="963" font-size="28" font-weight="bold">FRONT PORCH RECOVERY</text><text x="600" y="1005" font-size="24">fpr26.github.io/front-porch-recovery</text></g></svg>';
}
